#!/usr/bin/env python3
"""Extract the shared S0 activation pool once and commit all four banks together."""
import argparse
import torch
from transformers import AutoTokenizer

from steer_opd.compass_banks import make_common_banks
from steer_opd.compass_job import project_path, model_path
from steer_opd.compass_alignment import ByteLevelCodec
from steer_opd.compass_scoring import load_text_scorer
from steer_opd.direction_bank import file_sha256
from steer_opd.extraction import pool_question, usable_text
from steer_opd.execution_policy import require_execution_allowed
from steer_opd.resumable_core import atomic_json, atomic_torch, digest, read_json
from steer_opd.experiment_runtime import initialize_stage, StageCheckpoint, Progress


def build(config):
    require_execution_allowed(config)
    output=project_path(config['bank_dir']);runtime=initialize_stage(config,output)
    questions=read_json(project_path(config['questions']));roles=('teacher','reference','student')
    content_ids={}
    if config.get('bind_checkpoint_content'):
        from steer_opd.checkpoint_identity import checkpoint_content_id
        content_ids={r:checkpoint_content_id(model_path(config[r]),receipt_dir=output/'provenance/checkpoints') for r in roles}
    inputs=[];identities={}
    for question in questions:
        records=[read_json(project_path(config['reference_dirs'][role])/f"{question['id']}.json") for role in roles]
        if any(r['id']!=question['id'] or r.get('model')!=config[role] for role,r in zip(roles,records)):
            raise ValueError('Reference text question/model differs from configured role')
        if content_ids and any(r.get('model_content_id')!=content_ids[role] for role,r in zip(roles,records)):
            raise ValueError('Reference checkpoint contents changed')
        identity={'checkpoint':config['student'],'step':0,'layers':config['layers'],
            'question_hash':digest(question),'roles':list(roles),'text_record_hashes':[digest(r) for r in records],
            'boundary':'block_output_before_final_norm','backend':config.get('extraction_backend','hf_batched_static'),
            'runtime_binding':runtime,'checkpoint_content_ids':content_ids}
        identities[question['id']]=identity;inputs.append((question,records,identity))
    stage=StageCheckpoint(output,digest({'config':config,'runtime':runtime,'inputs':identities}))
    with Progress(output/'bank_progress','direction_banks',len(questions),unit='question') as progress:
        if stage.load() is not None:progress.resume(len(questions));return
        pooled={q['id']:{'usable':False,'reason':'common_text_quality_filter','identity':identity}
                for q,records,identity in inputs if not all(usable_text(r) for r in records)}
        valid_inputs=[item for item in inputs if item[0]['id'] not in pooled]
        tokenizer=AutoTokenizer.from_pretrained(model_path(config['student']),local_files_only=True)
        backend=config.get('extraction_backend','hf_batched_static')
        if backend=='easysteer':
            from steer_opd.easysteer_extraction import extract_all
            extract_all(config,tokenizer,valid_inputs,pooled)
        elif backend=='hf_batched_static':
            # Explicit numerical reference; the production configuration selects EasySteer.
            model=load_text_scorer(model_path(config['student']),ByteLevelCodec(tokenizer))
            model.model.layers=torch.nn.ModuleList(list(model.model.layers[:max(config['layers'])+1]))
            for question,records,identity in valid_inputs:
                artifacts={}
                def save(index,payload):
                    path=output/'token_activations'/question['id']/f'{roles[index]}.pt'
                    atomic_torch(path,{**payload,'identity':identity,'role':roles[index]})
                    artifacts[roles[index]]={'path':str(path.relative_to(project_path('.'))),'sha256':file_sha256(path)}
                pooled[question['id']]={**pool_question(model,tokenizer,question,records,config['layers'],save,
                    cache_dtype=torch.bfloat16,allow_zero=True),'identity':identity,'token_activations':artifacts}
        else:raise ValueError('Unknown extraction backend; no automatic fallback')
        valid=[q for q in questions if pooled[q['id']]['usable']]
        if len(valid)<config.get('minimum_pairs',8):raise ValueError('Too few common valid reference triplets')
        identity={'checkpoint':config['student'],'step':0,'reference_pool_hash':digest(identities)}
        if content_ids:identity['checkpoint_content_id']=content_ids['student']
        with progress.phase_scope('save_complete_extraction_and_four_banks'):
            # Freeze question order independently of capture completion order.
            pooled={q['id']:pooled[q['id']] for q in questions}
            banks,scales=make_common_banks(pooled,config['layers'],identity,alpha=config['alpha'])
            files=[];hashes={}
            for qid,value in pooled.items():
                path=output/'pooled'/f'{qid}.pt';atomic_torch(path,value);files.append(path)
                files.extend(project_path(a['path']) for a in value.get('token_activations',{}).values())
            for name,bank in banks.items():
                path=output/f'{name}.pt';atomic_torch(path,bank);files.append(path);hashes[name]=file_sha256(path)
            atomic_torch(output/'common_scales.pt',scales);atomic_json(output/'questions.json',valid)
            atomic_json(output/'manifest.json',{'valid_ids':[q['id'] for q in valid],'bank_sha256':hashes,
                'rejected':{qid:v.get('reason','unusable_activation') for qid,v in pooled.items() if not v['usable']},
                'identity_hash':digest(identities),'parameter_updates':0,'layers':config['layers'],'alpha':config['alpha']})
            files.extend(output/name for name in ('common_scales.pt','questions.json','manifest.json'))
            stage.commit(files,questions=len(questions),banks=4)
        progress.finished_call(len(questions));progress.mark_committed(len(questions))


def main():
    parser=argparse.ArgumentParser(description=__doc__);parser.add_argument('--config',required=True)
    args=parser.parse_args();build(read_json(args.config))


if __name__=='__main__':main()

source.scripts/run_static_overlap_screen.py:
#!/usr/bin/env python3
"""Prepare frozen masks on CPU, then optionally score all conditions, never train.

Inputs are unsteered source rows, raw student rollout Top16, teacher caches,
explicit metric identities and four S0 banks. Native IDs require the same
mapping. The separate Compass-style adapter uses aligned byte continuations;
it never labels its result as native cross-tokenizer token-ID overlap.
"""

import argparse
import os
from pathlib import Path

import torch

from steer_opd.direction_bank import file_sha256
from steer_opd.overlap_tuning import paired_summary, position_metrics
from steer_opd.resumable_core import ROOT, atomic_json, atomic_torch, digest, read_json
from steer_opd.static_masks import freeze_static_mask, native_overlap, validate_native_score
from steer_opd.static_screen import candidate_vectors, score_native_candidate
from steer_opd.method_config import Method
from steer_opd.execution_policy import require_default_scheduler_options, require_execution_allowed
from steer_opd.experiment_runtime import initialize_stage, StageCheckpoint, Progress


def path(value):
    result = Path(value)
    result = result if result.is_absolute() else ROOT / result
    if not result.resolve().is_relative_to(ROOT.resolve()):
        raise ValueError("Static screen inputs/outputs must stay within the project")
    return result


def prepare(job):
    from steer_opd.compass_alignment import METRIC
    if job.get("identity", {}).get("metric") == METRIC:
        from steer_opd.compass_job import prepare_screen
        return prepare_screen(job)
    if job.get("stage") != "static_overlap_screen" or job.get("optimizer_updates") != 0:
        raise ValueError("This entrypoint only accepts explicit zero-update static screens")
    if job["identity"]["metric"] != "native_overlap_at_16":
        raise ValueError("This native metric adapter cannot silently substitute for a cross-tokenizer event scorer")
    rows = read_json(path(job["rows"]))
    if not rows or len({row.get("key", row["id"]) for row in rows}) != len(rows):
        raise ValueError("Source response keys must be unique")
    masks, teachers = {}, {}
    banks = {name: torch.load(path(value), map_location="cpu", weights_only=True) for name, value in job["banks"].items()}
    conditions = job["conditions"]
    if len({c["id"] for c in conditions}) != len(conditions):
        raise ValueError("Duplicate candidate IDs")
    for condition in conditions:
        if Path(condition["id"]).name != condition["id"] or condition["id"] in (".", "..", "baseline", "masks"):
            raise ValueError("Unsafe or reserved candidate ID")
        if condition["gate"] not in ("all", "static_overlap"):
            raise ValueError("Only all/static_overlap are accepted by the static entrypoint")
        Method(direction=condition["direction"], granularity=condition["granularity"],
               layers=tuple(condition["layers"]), gate=condition["gate"], overlap_threshold=job["threshold"],
               operator=condition.get("operator", "slerp"), alpha=condition.get("alpha", .1) if condition.get("operator", "slerp") == "slerp" else None,
               rho=condition.get("rho", .03))
    for row in rows:
        key = row.get("key", row["id"])
        if Path(key).name != key or key in (".", ".."):
            raise ValueError("Response keys cannot contain path separators")
        if job.get("source_dir"):
            from steer_opd.rollout_topk import load_rollout_topk
            student_path = path(job["source_dir"]) / row["rollout_topk"]
            student = load_rollout_topk(path(job["source_dir"]), row, 16, job["support_size"])
            if row.get("model") != job["student"]:
                raise ValueError("Rollout model differs from frozen scoring student")
        else:
            student_path = path(job["student_scores"]) / f"{key}.pt"
            student = torch.load(student_path, map_location="cpu", weights_only=True)
        teacher_path = path(job["teacher_scores"]) / f"{key}.pt"
        teachers[key] = torch.load(teacher_path, map_location="cpu", weights_only=True)
        if student.get("source") not in ("vllm_rollout_raw_logprobs", "hf_controlled_rollout_raw_logprobs", "hf_unsteered_rollout_raw_logprobs"):
            raise ValueError("Source Top16 must come from an unsteered rollout, not a controlled probe")
        source_hash = digest({"prompt_token_ids": row["prompt_token_ids"], "token_ids": row["token_ids"]})
        for score in ([teachers[key]] if job.get("source_dir") else [student, teachers[key]]):
            if score.get("source_token_hash") != source_hash or score.get("support_size") != job["support_size"]:
                raise ValueError("Probability cache prefix or output support mismatch")
        if teachers[key].get("teacher_checkpoint") != job["identity"]["teacher_checkpoint"]:
            raise ValueError("Teacher probability cache checkpoint mismatch")
        for score in (student, teachers[key]):
            validate_native_score(score, len(row["token_ids"]), job["support_size"])
        identity = {**job["identity"], "student_score_sha256": file_sha256(student_path),
                    "teacher_score_sha256": file_sha256(teacher_path)}
        if identity["student_checkpoint"] != job["student"]:
            raise ValueError("Source checkpoint differs from scoring student")
        overlap = native_overlap(student["ids"], teachers[key]["ids"], identity)
        masks[key] = freeze_static_mask(row, overlap, job["threshold"], identity)
        for condition in conditions:
            bank = banks[condition["bank"]]
            if row["id"] not in bank["valid_ids"] or bank["identity"]["checkpoint"] != job["student"]:
                raise ValueError("Every scheme must share the same usable questions and S0 checkpoint")
            candidate_vectors(bank, row, condition)
    output = path(job["output"])
    frozen = {"job_hash": digest(job), "source_rows_hash": digest(rows),
              "masks": {k: v["mask_id"] for k, v in masks.items()},
              "bank_hashes": {k: file_sha256(path(p)) for k, p in job["banks"].items()}, "parameter_updates": 0}
    if (output / "manifest.json").exists() and read_json(output / "manifest.json") != frozen:
        raise ValueError("Cannot resume changed static screen inputs")
    for key, artifact in masks.items():
        atomic_json(output / "masks" / f"{key}.json", artifact)
    atomic_json(output / "manifest.json", frozen)
    return rows, masks, teachers, banks


def run(job, rows, masks, teachers, banks):
    require_execution_allowed(job)
    require_default_scheduler_options(job)
    runtime=initialize_stage(job,path(job["output"]))
    with Progress(path(job["output"]),"fixed_prefix_screen",len(rows)*(1+len(job["conditions"])),unit="score",show_bar=False) as progress:
        return _run(job,rows,masks,teachers,banks,runtime,progress)


def _run(job, rows, masks, teachers, banks, runtime, progress):
    from steer_opd.resumable_core import load_model, require_gpu
    from steer_opd.static_plotting import plot_comparisons, plot_dual_comparisons
    from steer_opd.compass_job import model_path
    os.environ["STEER_OPD_SUPPORT_SIZE"] = str(job["support_size"])
    output = path(job["output"])
    metric_adapter = getattr(teachers, "metric_adapter", None)
    plot_keys = ([r.get("key", r["id"]) for r in read_json(path(job["rows"]))[:3]]
                 if metric_adapter is not None else None)
    phase_binding = digest({"manifest":read_json(output / "manifest.json"),"runtime":runtime})
    stores = {}
    def plots(condition, base, records):
        plot = plot_dual_comparisons if job.get("require_dual_metrics") else plot_comparisons
        plot(rows, base, records, output / condition["id"] / "comparison", requested_keys=plot_keys)
    def cached(name):
        stores[name]=StageCheckpoint(output/name,digest({'candidate':name,'binding':phase_binding}))
        return stores[name].load_tensors([r.get("key",r["id"]) for r in rows])
    def commit(name,records):
        if ready[name] is None:
            with progress.phase_scope('save_complete_candidate',condition=name):
                stores[name].save_tensors(records)
            ready[name]=records
            progress.mark_committed(progress.committed+len(rows))
    required = ["baseline", *[c["id"] for c in job["conditions"]]]
    ready = {name: cached(name) for name in required}
    progress.resume(sum(len(v) for v in ready.values() if v is not None))
    if all(ready[name] is not None for name in required) and (output / "complete.json").exists():
        # Rebuild requested CPU plots from cached data if necessary.
        for condition in job["conditions"]:
            plots(condition, ready["baseline"], ready[condition["id"]])
        print("All static conditions already complete; reused committed probability records")
        return
    needs_model = any(ready[name] is None for name in required)
    backend = job.get("backend", "hf_batched_static")
    if backend not in ("hf_batched_static", "easysteer"):
        raise ValueError("Unknown static backend; no automatic backend substitution")
    if needs_model:
        from steer_opd.experiment_runtime import compute_required
        compute_required()
        if backend == "easysteer":
            from steer_opd.easysteer_static import require_easysteer_gpu
            require_easysteer_gpu()
        else:
            require_gpu()
    model = None
    if needs_model and backend == "hf_batched_static":
        if metric_adapter is None:
            model = load_model(model_path(job["student"]))
        else:
            from steer_opd.compass_scoring import load_text_scorer
            model = load_text_scorer(model_path(job["student"]), metric_adapter.student_codec, metric_adapter.teacher_codec)
    elif needs_model:
        from steer_opd.easysteer_static import engine_options, require_easysteer
        require_easysteer()
        if metric_adapter is not None and metric_adapter.student_codec.valid_ids != list(range(job["support_size"])):
            raise ValueError("EasySteer support cropping requires a contiguous defined student vocabulary")
        os.environ["STEER_OPD_STATIC_SUPPORT"] = str(job["support_size"])
        from steer_opd.easysteer_static import create_engine
        projection = None
        if job.get("require_dual_metrics"):
            from steer_opd.byte_probabilities import projection_spec
            projection = output / "student_projection.pt"
            atomic_torch(projection, projection_spec(metric_adapter.student_codec, metric_adapter.teacher_codec))
        model = create_engine(model_path(job["student"]), job["support_size"],
            max_model_len=max(len(r["prompt_token_ids"])+len(r["token_ids"]) for r in rows)+1,
            gpu_memory_utilization=job.get("gpu_memory_utilization", .75), projection_path=projection, seed=42, progress=progress,batch_invariant=True)
    def evaluate(condition):
        name=condition["id"] if condition else "baseline"
        if ready[name] is not None:return ready[name]
        start=progress.done
        bank=banks[condition["bank"]] if condition else next(iter(banks.values()))
        if backend=="hf_batched_static":
            records=score_native_candidate(model,rows,teachers,masks,bank,condition,
                baseline=baseline if condition else None,batch_size=job.get("batch_size",4),
                chunk=job.get("chunk",128),metric_adapter=metric_adapter)
        else:
            records=evaluate_engine(condition,bank)
        progress.finished_call(start+len(rows))
        # All distributions are available: derive metrics/deltas after the engine call.
        for key,record in records.items():
            if condition:
                for metric in (("overlap","P_overlap") if job.get("require_dual_metrics") else ("overlap",)):
                    record[f"delta_{metric}"]=record[metric]-baseline[key][metric]
            else:
                gate=job.get("gate_metric","overlap")
                for metric,values in masks[key].get("source_metrics",{gate:masks[key]["source_overlap"]}).items():
                    record[f"source_rollout_vs_replay_delta_{metric}"]=record[metric].double()-torch.tensor(
                        [float("nan") if v is None else v for v in values],dtype=torch.float64)
                record["source_rollout_vs_replay_delta"]=record[f"source_rollout_vs_replay_delta_{gate}"]
        return records
    def evaluate_engine(condition,bank):
        from steer_opd.easysteer_static import build_spec, fixed_prefix_scores
        specs, meta = [], []
        for row in rows:
            key = row.get("key", row["id"])
            if condition:
                vectors, vector_id = candidate_vectors(bank, row, condition)
                requested = masks[key]["requested_mask"] if condition["gate"] == "static_overlap" else [True]*len(row["token_ids"])
                nonzero = any(bool(torch.count_nonzero(v)) for v in vectors.values())
                active = nonzero and condition.get("alpha", .1) != 0
                actual = [g and active for g in requested]
                spec = build_spec(row, actual, vectors, operator=condition.get("operator", "slerp"), alpha=condition.get("alpha", .1))
            else:
                vector_id, requested, actual, spec, nonzero = None, [False]*len(row["token_ids"]), [False]*len(row["token_ids"]), False, False
            specs.append(spec)
            meta.append({"mask_id": masks[key]["mask_id"], "source_binding": masks[key]["source_binding"],
                "binding": digest({"mask_id": masks[key]["mask_id"], "condition": condition, "vector_id": vector_id}),
                "vector_id": vector_id, "condition": condition, "requested_mask": torch.tensor(requested),
                "steering_mask": torch.tensor(actual), "relative_perturbation_available": False,
                "zero_vector_no_intervention": bool(condition is not None and not nonzero)})
        with progress.phase_scope('continuous_candidate_scoring',condition=None if condition is None else condition['id']):
            scores=fixed_prefix_scores(model,rows,specs,include_sampled=metric_adapter is not None,
                collect_byte_probs=job.get("require_dual_metrics",False),progress=progress)
        with progress.phase_scope('compute_candidate_metrics'):
            return {r.get("key",r["id"]):{**score,
                **(position_metrics(score,teachers[r.get("key",r["id"])]) if metric_adapter is None else
                   metric_adapter(r.get("key",r["id"]),score,teachers[r.get("key",r["id"])])),**metadata}
                for r,score,metadata in zip(rows,scores,meta)}
    baseline=evaluate(None)
    commit("baseline",baseline)
    summaries = {}
    for condition in job["conditions"]:
        records = evaluate(condition)
        # Aggregate multiple responses by question before paired_summary.
        def by_question(values, metric="overlap"):
            groups = {}
            for row in rows:
                groups.setdefault(row["id"], []).append(values[row.get("key", row["id"])])
            return {qid: {name: torch.cat([v[metric if name == "overlap" else name][v.get("alignment_mask", torch.ones_like(v[metric], dtype=torch.bool))] for v in items]) for name in
                          ("overlap", "student_shared_mass", "teacher_shared_mass")} for qid, items in groups.items()}
        metric_names = ("overlap", "P_overlap") if job.get("require_dual_metrics") else ("overlap",)
        metric_summaries = {}
        for name in metric_names:
            summary = paired_summary(by_question(records, name), by_question(baseline, name))
            if name == "P_overlap":
                summary["token_weighted_value"] = summary.pop("token_weighted_overlap16")
                summary.pop("student_shared_mass"); summary.pop("teacher_shared_mass")
            summary["metric_name"] = name
            summary["question_weighted_value"] = sum(float(v["overlap"].mean()) for v in by_question(records, name).values()) / summary["questions"]
            total = sum(len(row["token_ids"]) for row in rows)
            summary.update(source_prediction_positions=total, valid_position_fraction=summary["positions"] / total,
                valid_span_count=sum(record.get("valid_span_count", 0) for record in records.values()),
                total_span_count=sum(record.get("total_span_count", 0) for record in records.values()),
                actual_steering_rate=sum(int(record["steering_mask"].sum()) for record in records.values()) / total)
            metric_summaries[name] = summary
            for row in rows:
                key = row.get("key", row["id"])
                records[key][f"delta_{name}"] = records[key][name]-baseline[key][name]
        rank_metric = job.get("rank_metric", "overlap")
        summaries[condition["id"]] = {"condition": condition, "metric": job["identity"]["metric"],
            "ranking_metric": rank_metric, "metrics": metric_summaries,
            **metric_summaries[rank_metric]}
        atomic_json(output / "summaries.json", summaries)
        # Deltas are derived from the committed baseline; persist both readouts.
        commit(condition["id"], records)
        with progress.phase_scope("plotting",condition=condition["id"]):
            plots(condition, baseline, records)
    atomic_json(output / "complete.json", {"status": "awaiting_user_review", "parameter_updates": 0,
                "candidates": len(summaries), "backend": backend, "automatic_opd": False})


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--job", required=True)
    parser.add_argument("--execute", action="store_true", help="Score on an admitted GPU; default only prepares masks on CPU")
    args = parser.parse_args()
    job = read_json(args.job)
    require_default_scheduler_options(job)
    if args.execute:
        require_execution_allowed(job)
    prepared = prepare(job)
    if args.execute:
        run(job, *prepared)
    else:
        print(f"CPU preparation complete: {len(prepared[0])} sources, {len(job['conditions'])} candidates; no model loaded")


if __name__ == "__main__":
    main()

source.scripts/validate_static_gpu.py:
#!/usr/bin/env python3
"""Small EasySteer contract checks, with an optional separate HF comparison."""
import argparse

import torch

from steer_opd.byte_probabilities import projection_spec,validate_byte_probabilities
from steer_opd.compass_job import load_codecs,model_path,project_path
from steer_opd.experiment_runtime import initialize_stage,StageCheckpoint,Progress
from steer_opd.math_data import prompt_ids
from steer_opd.resumable_core import atomic_json,atomic_torch,digest,read_json

# Fixed BF16 acceptance tolerances, never widened on failure.
LIMITS={'mean_abs_logp':.05,'max_abs_logp':.2,'max_byte_tv':.03,'max_hidden_relative_l2':.03}


def compare_scores(reference,actual):
    if len(reference)!=len(actual):raise ValueError('Validation score row count changed')
    for a,b in zip(reference,actual):
        for value in (a,b):validate_byte_probabilities(value['byte_probs'],len(value['sampled_logps']))
    errors=torch.cat([(a['sampled_logps']-b['sampled_logps']).abs() for a,b in zip(reference,actual)])
    tv=float(torch.stack([(a['byte_probs']-b['byte_probs']).abs().sum(-1).max()/2 for a,b in zip(reference,actual)]).max())
    result={'mean_abs_logp':float(errors.mean()),'max_abs_logp':float(errors.max()),'max_byte_tv':tv}
    if any(not torch.isfinite(torch.tensor(v)) or v>LIMITS[k] for k,v in result.items()):
        raise ValueError(f'GPU probability parity failed: {result}; limits={LIMITS}')
    return result


def hf_capture(model,rows,layers):
    device=model._input_device;lengths=[len(r['prompt_token_ids'])+len(r['token_ids']) for r in rows]
    tokens=torch.zeros((len(rows),max(lengths)),dtype=torch.long,device=device);attention=torch.zeros_like(tokens)
    for i,row in enumerate(rows):
        tokens[i,:lengths[i]]=torch.tensor(row['prompt_token_ids']+row['token_ids'],device=device);attention[i,:lengths[i]]=1
    captured={};hooks=[]
    for layer in layers:
        def save(module,args,value,layer=layer):
            captured[layer]=(value[0] if isinstance(value,tuple) else value).detach().cpu().clone()
        hooks.append(model.model.layers[layer].register_forward_hook(save))
    try:
        with torch.inference_mode():model.model(input_ids=tokens,attention_mask=attention,use_cache=False)
    finally:
        for hook in hooks:hook.remove()
    return [{str(l):captured[l][i,len(r['prompt_token_ids'])-1:lengths[i]] for l in layers} for i,r in enumerate(rows)]


def run(job,role,backend):
    if job.get('stage')!='static_gpu_acceptance' or job.get('optimizer_updates')!=0 or job.get('execution_hold'):
        raise ValueError('Expected an explicitly requested zero-update validation job')
    output=project_path(job['run_dir'])/'acceptance'/role/backend
    runtime=initialize_stage(job,output)
    store=StageCheckpoint(output,digest({'runtime':runtime,'binding':job['gpu_acceptance_binding'],'role':role,'backend':backend}))
    with Progress(output,'validate_'+role+'_'+backend,1,unit='check',show_bar=False) as progress:
        if store.load() is not None:progress.resume(1);return
        codecs=load_codecs(job);codec=codecs[role]
        use_hf=job.get('startup_hf_parity',False)
        if backend=='hf':
            if not use_hf:raise ValueError('HF numerical comparison was not explicitly enabled')
            progress.phase='hf_reference'
            from steer_opd.compass_scoring import load_text_scorer
            from steer_opd.static_screen import score_batch
            model=load_text_scorer(model_path(job[role]),codec,codecs['teacher' if role=='student' else 'student'])
            rows=[{'id':str(i),'key':str(i),'prompt_token_ids':prompt_ids(codec.tokenizer,q,enable_thinking=False),
                   'token_ids':codec.tokenizer.encode(answer,add_special_tokens=False)+[min(codec.eos)]}
                  for i,(q,answer) in enumerate([('What is 2 + 3?','The answer is 5.'),('Compute 7 - 2.','5.')])]
            reference={'rows':rows,'baseline':score_batch(model,rows)}
            if role=='student':
                states=hf_capture(model,rows,job['layers'])
                vector={l:states[0][str(l)][1:].float().mean(0) for l in job['layers']}
                vectors=[vector,{l:-v.flip(0) for l,v in vector.items()}]
                gates=[[i%2==j for i in range(len(r['token_ids']))] for j,r in enumerate(rows)]
                reference.update(captured=states,vectors=vectors,gates=gates)
                for name,masks in [('static',gates),('all',[[True]*len(r['token_ids']) for r in rows])]:
                    reference[name]=score_batch(model,rows,vectors=vectors,gates=masks,alpha=job['alpha'])
            store.save_tensors({'reference':reference})
        else:
            from steer_opd.easysteer_static import create_engine,fixed_prefix_scores,build_spec
            from steer_opd.engine_projection import select_prediction_statistics
            if use_hf:
                reference=torch.load(output.parent/'hf/reference.pt',map_location='cpu',weights_only=True);rows=reference['rows']
            else:
                rows=[{'id':str(i),'key':str(i),'prompt_token_ids':prompt_ids(codec.tokenizer,q,enable_thinking=False),
                       'token_ids':codec.tokenizer.encode(answer,add_special_tokens=False)+[min(codec.eos)]}
                      for i,(q,answer) in enumerate([('What is 2 + 3?','The answer is 5.'),('Compute 7 - 2.','5.')])]
                reference={'rows':rows}
            projection=output/'projection.pt';atomic_torch(projection,projection_spec(codec,codecs['teacher' if role=='student' else 'student']))
            engine=create_engine(model_path(job[role]),codec.support_size,max_model_len=256,
                tensor_parallel_size=job['teacher_gpus'] if role=='teacher' else 1,
                gpu_memory_utilization=job['gpu_memory_utilization'],projection_path=projection,
                capture_sampled=role=='student',progress=progress,batch_invariant=role=='student')
            progress.phase='numerical_parity'
            def score(specs):return fixed_prefix_scores(engine,rows,specs,include_sampled=True,collect_byte_probs=True)
            baseline=score([False]*len(rows))
            report={'hf_parity':use_hf,'limits':LIMITS,
                'baseline':compare_scores(reference['baseline'] if use_hf else score([False]*len(rows)),baseline)}
            if role=='student':
                import easysteer.capture as hs
                from vllm.capture import SelectSpec
                result=hs.capture(engine,[{'prompt_token_ids':r['prompt_token_ids']+r['token_ids']} for r in rows],
                    layers=job['layers'],dtype='bfloat16',steering=False,seed=42,
                    per_prompt_selects=[SelectSpec(prompt_positions=list(range(len(r['prompt_token_ids'])-1,
                        len(r['prompt_token_ids'])+len(r['token_ids'])))) for r in rows])
                if list(result.layer_ids)!=job['layers'] or len(result.outputs)!=len(rows):
                    raise ValueError('Capture layers or sample count differ')
                if not use_hf:
                    reference['captured']=[{str(l):v.cpu() for l,v in result.sample(i).items()} for i in range(len(rows))]
                    vector={l:reference['captured'][0][str(l)][1:].float().mean(0) for l in job['layers']}
                    reference['vectors']=[vector,{l:-v.flip(0) for l,v in vector.items()}]
                    reference['gates']=[[i%2==j for i in range(len(r['token_ids']))] for j,r in enumerate(rows)]
                hidden_error=0.
                for i,row in enumerate(rows):
                    expected=list(range(len(row['prompt_token_ids'])-1,len(row['prompt_token_ids'])+len(row['token_ids'])))
                    tokens=row['prompt_token_ids']+row['token_ids']
                    if result.sample_positions(i)!=expected or result.sample_token_ids(i)!=[tokens[p] for p in expected]:
                        raise ValueError('Capture position/token labels differ')
                    for layer,values in result.sample(i).items():
                        other=reference['captured'][i][str(layer)].float()
                        delta=(values.float()-other).norm(dim=-1)/other.norm(dim=-1).clamp_min(1e-8)
                        if not torch.isfinite(delta).all():raise ValueError('Nonfinite captured states')
                        hidden_error=max(hidden_error,float(delta.max()))
                if not torch.isfinite(torch.tensor(hidden_error)) or hidden_error>LIMITS['max_hidden_relative_l2']:
                    raise ValueError(f'Capture parity failed: relative L2={hidden_error}')
                if use_hf:report['max_hidden_relative_l2']=hidden_error
                else:report['capture_positions_tokens_and_finite_states']='passed'
                for name,masks in [('static',reference['gates']),('all',[[True]*len(r['token_ids']) for r in rows])]:
                    specs=[build_spec(r,g,v,alpha=job['alpha']) for r,g,v in zip(rows,masks,reference['vectors'])]
                    actual=score(specs)
                    expected=(reference[name] if use_hf else [fixed_prefix_scores(engine,[r],[s],include_sampled=True,collect_byte_probs=True)[0]
                                for r,s in zip(rows,specs)])
                    report[name]=compare_scores(expected,actual)
                    if name=='all' and job['alpha']>=.01 and all(torch.equal(a['sampled_logps'],b['sampled_logps']) for a,b in zip(baseline,actual)):
                        raise ValueError('Nonzero steering produced no change')
                for name,specs in [('alpha0',[build_spec(r,[True]*len(r['token_ids']),v,alpha=0) for r,v in zip(rows,reference['vectors'])]),
                                   ('empty_mask',[build_spec(r,[False]*len(r['token_ids']),v,alpha=job['alpha']) for r,v in zip(rows,reference['vectors'])]),
                                   ('removed',[False]*len(rows))]:
                    unchanged=score(specs)
                    for a,b in zip(baseline,unchanged):torch.testing.assert_close(a['sampled_logps'],b['sampled_logps'],atol=1e-5,rtol=1e-5)
                    report[name]='passed'
                # Native source sampling and frozen-prefix replay use the same actual tokens.
                from vllm import SamplingParams
                outputs=engine.generate([{'prompt_token_ids':r['prompt_token_ids']} for r in rows],
                    SamplingParams(max_tokens=8,temperature=1,seed=42,logprobs=16,stop_token_ids=sorted(codec.eos)),
                    steering=False,use_tqdm=True)
                source=[];replay_rows=[]
                for row,out in zip(rows,outputs):
                    sample=out.outputs[0];record={**row,'token_ids':list(sample.token_ids)};replay_rows.append(record)
                    stats=select_prediction_statistics(engine.collective_rpc('project_pop_byte_statistics',args=(out.request_id,)),record)
                    source.append({**stats,'sampled_logps':torch.tensor([float(step[t].logprob) for t,step in zip(sample.token_ids,sample.logprobs)])})
                replay=fixed_prefix_scores(engine,replay_rows,[False]*len(rows),include_sampled=True,collect_byte_probs=True)
                report['source_replay']=compare_scores(source,replay)
            atomic_json(output/'report.json',report)
            store.commit([projection,output/'report.json'])
        progress.finished_call(1);progress.mark_committed(1)


def main():
    p=argparse.ArgumentParser(description=__doc__);p.add_argument('--job',required=True)
    p.add_argument('--role',choices=['student','reference','teacher'],required=True)
    p.add_argument('--backend',choices=['hf','easysteer'],required=True)
    args=p.parse_args();run(read_json(args.job),args.role,args.backend)


if __name__=='__main__':main()

